SELECT assert_true((SELECT count(*)=3 AND bool_and(event_type='baseline' AND before_terms IS NULL AND actor_id IS NULL) FROM accounting_agreement_history),'baseline describes installation observations with an honest system actor');
SELECT assert_true((SELECT bool_and(NOT(after_terms ?| ARRAY['chip_balance','agent_wallet_balance','weekly_rake_generated','notes'])) FROM accounting_agreement_history),'wallet counters and private notes never enter agreement snapshots');
UPDATE agents SET agent_wallet_balance=501,weekly_rake_generated=11 WHERE id=u(1);
UPDATE club_members SET chip_balance=101 WHERE user_id=u(12);
SELECT assert_true((SELECT count(*)=3 FROM accounting_agreement_history),'balance traffic does not create agreement events');
UPDATE agents SET commission_rate=commission_rate WHERE id=u(1);
SELECT assert_true((SELECT count(*)=3 FROM accounting_agreement_history),'replaying unchanged terms does not add an event');
SELECT set_config('test.uid',u(99)::text,false);
UPDATE agents SET commission_rate=0.65,player_rakeback_rate=0.25 WHERE id=u(1);
SELECT assert_true((SELECT actor_id=u(99) AND before_terms->>'commission_rate'='0.6' AND after_terms->>'commission_rate'='0.65' FROM accounting_agreement_history ORDER BY id DESC LIMIT 1),'both rates and the actual actor are captured together');
UPDATE club_members SET agent_id=u(13),player_rakeback_pct=0.15 WHERE user_id=u(12);
SELECT assert_true((SELECT before_terms->>'agent_id'=u(11)::text AND after_terms->>'agent_id'=u(13)::text AND after_terms->>'player_rakeback_pct'='0.15' FROM accounting_agreement_history ORDER BY id DESC LIMIT 1),'reassignment and negotiated player rate are recorded atomically');
UPDATE union_clubs SET rate_spin=0.89 WHERE id=u(2);
SELECT assert_true((SELECT before_terms->>'rate_spin'='0.87' AND after_terms->>'rate_spin'='0.89' FROM accounting_agreement_history ORDER BY id DESC LIMIT 1),'game-specific union allocation changes are retained');
UPDATE club_members SET club_id=u(30) WHERE user_id=u(12);
SELECT assert_true((SELECT after_terms IS NULL FROM accounting_agreement_history WHERE entity_type='club_members' AND club_id=u(10) ORDER BY id DESC LIMIT 1),'moving clubs closes the original membership identity');
SELECT assert_true((SELECT before_terms IS NULL AND after_terms->>'club_id'=u(30)::text FROM accounting_agreement_history WHERE entity_type='club_members' AND club_id=u(30) ORDER BY id DESC LIMIT 1),'moving clubs establishes the new identity without a false prior state');
DELETE FROM agents WHERE id=u(1);
SELECT assert_true((SELECT before_terms->>'commission_rate'='0.65' AND after_terms IS NULL AND event_type='DELETE' FROM accounting_agreement_history ORDER BY id DESC LIMIT 1),'deletion preserves the last observed agreement');
SELECT assert_true(refuses('UPDATE accounting_agreement_history SET event_type=''baseline'' WHERE id=1','55000'),'history cannot be edited');
SELECT assert_true(refuses('DELETE FROM accounting_agreement_history WHERE id=1','55000'),'history cannot be deleted');
SELECT assert_true(refuses('TRUNCATE accounting_agreement_history','55000'),'history cannot be truncated');
DO $$DECLARE n bigint; BEGIN SELECT count(*) INTO n FROM accounting_agreement_history; BEGIN UPDATE union_clubs SET rate_cash=0.8 WHERE id=u(2); RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='rollback probe'; EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL; END; PERFORM assert_true((SELECT count(*)=n FROM accounting_agreement_history) AND (SELECT rate_cash=0.9 FROM union_clubs WHERE id=u(2)),'a rolled-back agreement change leaves neither terms nor an audit event'); END$$;
SELECT assert_true(NOT has_table_privilege('authenticated','accounting_agreement_history','SELECT') AND NOT has_table_privilege('authenticated','accounting_agreement_history','INSERT'),'clients cannot read another agreement or forge history');
SELECT assert_true(has_table_privilege('service_role','accounting_agreement_history','SELECT') AND NOT has_table_privilege('service_role','accounting_agreement_history','INSERT'),'server can reconcile history but cannot manually append fabricated events');
